messages.content:
I'll build you an interactive artifact that walks through Picard–Lindelöf — the statement, the Lipschitz condition, and the contraction-mapping iteration that proves it.

<artifact type="html" id="picard-lindelof-explorer" title="Picard–Lindelöf theorem explorer">
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, -apple-system, sans-serif; margin: 0; padding: 16px; background: #faf8f3; color: #2a2520; line-height: 1.5; }
  h2 { margin-top: 0; color: #6b3410; }
  h3 { color: #8b4513; margin-bottom: 6px; }
  .panel { background: white; border: 1px solid #d8c8a8; border-radius: 8px; padding: 14px; margin-bottom: 12px; }
  .theorem { background: #fff8e8; border-left: 4px solid #c4862a; }
  .controls { display: flex; gap: 16px; flex-wrap: wrap; align-items: center; margin: 8px 0; }
  .control { display: flex; flex-direction: column; font-size: 13px; }
  label { font-weight: 600; color: #5a3a1a; }
  input[type=range] { width: 180px; }
  select, button { padding: 6px 10px; font-size: 13px; border: 1px solid #c4a878; border-radius: 4px; background: white; cursor: pointer; }
  button:hover { background: #f5e8d0; }
  canvas { display: block; margin: 8px auto; border: 1px solid #d8c8a8; border-radius: 4px; background: white; }
  .formula { background: #f8f3e8; padding: 8px 12px; border-radius: 4px; margin: 8px 0; }
  .legend { font-size: 12px; display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; margin-top: 4px; }
  .swatch { display: inline-block; width: 14px; height: 3px; vertical-align: middle; margin-right: 4px; }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; margin-left: 6px; }
  .ok { background: #d4edda; color: #155724; }
  .bad { background: #f8d7da; color: #721c24; }
  .step-info { font-size: 13px; color: #5a3a1a; min-height: 38px; }
</style>
</head>
<body>

<h2>Picard–Lindelöf: Existence & Uniqueness</h2>

<div class="panel theorem">
  <h3>Theorem</h3>
  Let $f:[t_0-a, t_0+a]\times \overline{B_b(x_0)} \to \mathbb{R}^n$ be continuous and <b>Lipschitz in $x$</b>:
  $$\|f(t,x) - f(t,y)\| \le L\,\|x-y\|.$$
  Then the IVP $\dot{x}=f(t,x),\ x(t_0)=x_0$ has a <b>unique</b> solution on $[t_0-\alpha, t_0+\alpha]$ where $\alpha = \min(a, b/M)$ and $M=\sup\|f\|$.
</div>

<div class="panel">
  <h3>1. The integral reformulation</h3>
  Solving the IVP is equivalent to finding a fixed point of the operator
  $$ (T\varphi)(t) = x_0 + \int_{t_0}^{t} f(s, \varphi(s))\,ds.$$
  We iterate from a starting guess $\varphi_0(t) \equiv x_0$ and watch $\varphi_{k+1} = T\varphi_k$ converge.
</div>

<div class="panel">
  <h3>2. Iteration explorer</h3>
  <div class="controls">
    <div class="control">
      <label>Equation</label>
      <select id="eq">
        <option value="exp">$\dot x = x,\ x(0)=1$ (true: $e^t$)</option>
        <option value="lin">$\dot x = -2x,\ x(0)=1$ (true: $e^{-2t}$)</option>
        <option value="quad">$\dot x = x^2,\ x(0)=1$ (true: $1/(1-t)$, blow-up!)</option>
        <option value="sqrt">$\dot x = \sqrt{|x|},\ x(0)=0$ (NOT Lipschitz)</option>
      </select>
    </div>
    <div class="control">
      <label>Iterations: <span id="kVal">3</span></label>
      <input type="range" id="k" min="0" max="8" value="3">
    </div>
    <button id="step">Step +1</button>
    <button id="reset">Reset</button>
  </div>
  <div class="step-info" id="info"></div>
  <canvas id="cv" width="640" height="340"></canvas>
  <div class="legend">
    <span><span class="swatch" style="background:#999"></span>true solution</span>
    <span><span class="swatch" style="background:#c44"></span>$\varphi_k$ (current)</span>
    <span><span class="swatch" style="background:#fbb"></span>previous iterates</span>
  </div>
</div>

<div class="panel">
  <h3>3. Why Lipschitz matters: contraction</h3>
  On a small interval of length $\alpha < 1/L$, the operator $T$ is a contraction:
  $$\|T\varphi - T\psi\|_\infty \le L\alpha\,\|\varphi-\psi\|_\infty.$$
  Banach's fixed-point theorem then gives a <b>unique</b> fixed point — the solution. Without Lipschitz, this contraction estimate fails. Try $\dot x=\sqrt{|x|}$ above and notice the iteration stays at 0, while in fact infinitely many other solutions exist.
</div>

<script>
const eqs = {
  exp:  { f:(t,x)=>x,         true:t=>Math.exp(t),         t0:0, x0:1, T:1.5,  L:1,   lip:true,  name:"ẋ = x" },
  lin:  { f:(t,x)=>-2*x,      true:t=>Math.exp(-2*t),      t0:0, x0:1, T:1.5,  L:2,   lip:true,  name:"ẋ = -2x" },
  quad: { f:(t,x)=>x*x,       true:t=>1/(1-t),             t0:0, x0:1, T:0.8,  L:null,lip:"local",name:"ẋ = x²" },
  sqrt: { f:(t,x)=>Math.sqrt(Math.abs(x))*(x<0?-1:1), true:t=>0, t0:0, x0:0, T:2, L:null, lip:false, name:"ẋ = √|x|" }
};

const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
const W = cv.width, H = cv.height;

let currentEq = 'exp';
let kMax = 3;

// Picard iterates as arrays of (t, value) sampled densely
function picardIterate(eq, k, N=200) {
  const ts = [];
  for (let i=0;i<=N;i++) ts.push(eq.t0 + (eq.T)*i/N);
  // start phi_0(t) = x0
  let phi = ts.map(_ => eq.x0);
  const all = [phi.slice()];
  for (let j=1;j<=k;j++) {
    const next = new Array(ts.length);
    next[0] = eq.x0;
    // trapezoid integration of f(s, phi(s))
    let acc = 0;
    for (let i=1;i<ts.length;i++) {
      const dt = ts[i]-ts[i-1];
      const f1 = eq.f(ts[i-1], phi[i-1]);
      const f2 = eq.f(ts[i],   phi[i]);
      // guard against blow up
      const inc = 0.5*(f1+f2)*dt;
      acc += isFinite(inc)?inc:0;
      next[i] = eq.x0 + acc;
    }
    phi = next;
    all.push(phi.slice());
  }
  return { ts, all };
}

function draw() {
  const eq = eqs[currentEq];
  const { ts, all } = picardIterate(eq, kMax);

  // compute y range
  let ymin = Infinity, ymax = -Infinity;
  const trueVals = ts.map(t => {
    const v = eq.true(t);
    return isFinite(v) && Math.abs(v) < 1e6 ? v : null;
  });
  trueVals.forEach(v => { if (v!==null){ if(v<ymin)ymin=v; if(v>ymax)ymax=v; }});
  all.forEach(phi => phi.forEach(v => {
    if (isFinite(v) && Math.abs(v) < 1e6) {
      if (v<ymin) ymin=v; if (v>ymax) ymax=v;
    }
  }));
  if (ymin === ymax) { ymin -= 1; ymax += 1; }
  const pad = 0.15*(ymax-ymin);
  ymin -= pad; ymax += pad;

  ctx.clearRect(0,0,W,H);
  // axes
  const ml = 50, mr = 16, mt = 16, mb = 30;
  const pw = W-ml-mr, ph = H-mt-mb;
  const X = t => ml + ((t-eq.t0)/eq.T)*pw;
  const Y = v => mt + (1 - (v-ymin)/(ymax-ymin))*ph;

  // grid
  ctx.strokeStyle = '#eee'; ctx.lineWidth = 1;
  for (let i=0;i<=5;i++){
    const x = ml + i*pw/5;
    ctx.beginPath(); ctx.moveTo(x,mt); ctx.lineTo(x,mt+ph); ctx.stroke();
    const y = mt + i*ph/5;
    ctx.beginPath(); ctx.moveTo(ml,y); ctx.lineTo(ml+pw,y); ctx.stroke();
  }
  // axis labels
  ctx.fillStyle = '#555'; ctx.font='11px sans-serif';
  ctx.textAlign='center';
  for (let i=0;i<=5;i++){
    const t = eq.t0 + i*eq.T/5;
    ctx.fillText(t.toFixed(2), ml + i*pw/5, mt+ph+14);
  }
  ctx.textAlign='right';
  for (let i=0;i<=5;i++){
    const v = ymax - i*(ymax-ymin)/5;
    ctx.fillText(v.toFixed(2), ml-4, mt + i*ph/5 + 4);
  }
  ctx.textAlign='center';
  ctx.fillText('t', ml+pw/2, H-6);

  // axis frame
  ctx.strokeStyle = '#888'; ctx.lineWidth=1;
  ctx.strokeRect(ml,mt,pw,ph);

  // true solution
  ctx.strokeStyle = '#999'; ctx.lineWidth=2; ctx.setLineDash([6,4]);
  ctx.beginPath();
  let started = false;
  for (let i=0;i<ts.length;i++){
    const v = trueVals[i];
    if (v===null) { started=false; continue; }
    const px = X(ts[i]), py = Y(v);
    if (!started){ ctx.moveTo(px,py); started=true; } else ctx.lineTo(px,py);
  }
  ctx.stroke(); ctx.setLineDash([]);

  // previous iterates faded
  for (let j=0;j<all.length-1;j++){
    const a = 0.25 + 0.4*(j/Math.max(1,all.length-1));
    ctx.strokeStyle = `rgba(204,68,68,${a*0.5})`;
    ctx.lineWidth=1.2;
    ctx.beginPath();
    let s=false;
    for (let i=0;i<ts.length;i++){
      const v = all[j][i];
      if (!isFinite(v) || Math.abs(v)>1e6){ s=false; continue;}
      const px=X(ts[i]), py=Y(v);
      if (!s){ ctx.moveTo(px,py); s=true;} else ctx.lineTo(px,py);
    }
    ctx.stroke();
  }
  // current iterate bold
  ctx.strokeStyle = '#c44'; ctx.lineWidth=2.5;
  ctx.beginPath();
  let s=false;
  const cur = all[all.length-1];
  for (let i=0;i<ts.length;i++){
    const v = cur[i];
    if (!isFinite(v) || Math.abs(v)>1e6){ s=false; continue;}
    const px=X(ts[i]), py=Y(v);
    if (!s){ ctx.moveTo(px,py); s=true;} else ctx.lineTo(px,py);
  }
  ctx.stroke();

  // info text
  let badge = '';
  if (eq.lip === true) badge = '<span class="badge ok">Lipschitz globally ✓</span>';
  else if (eq.lip === 'local') badge = '<span class="badge ok">Lipschitz locally ✓ (but solution blows up at t=1)</span>';
  else badge = '<span class="badge bad">NOT Lipschitz at x=0 ✗</span>';

  let msg = `<b>${eq.name}</b> ${badge}<br>`;
  if (eq.lip === false) {
    msg += `Iterates stay at 0 forever — Picard converges to the trivial solution, but $x(t)=t^2/4$ is also a solution. Uniqueness fails.`;
  } else if (eq.lip === 'local') {
    msg += `Iteration converges only on $[0, \\alpha)$ with $\\alpha < 1$. Beyond that, the true solution escapes to infinity.`;
  } else {
    msg += `Iteration converges uniformly to the true solution on $[0, T]$. After $k=${kMax}$ steps, max error ≈ ${maxErr(cur, trueVals).toExponential(2)}.`;
  }
  document.getElementById('info').innerHTML = msg;
  if (window.renderMathInElement) window.renderMathInElement(document.getElementById('info'));
}

function maxErr(approx, truth){
  let m=0;
  for (let i=0;i<approx.length;i++){
    if (truth[i]===null || !isFinite(approx[i])) continue;
    m = Math.max(m, Math.abs(approx[i]-truth[i]));
  }
  return m;
}

document.getElementById('eq').addEventListener('change', e => {
  currentEq = e.target.value;
  draw();
});
document.getElementById('k').addEventListener('input', e => {
  kMax = +e.target.value;
  document.getElementById('kVal').textContent = kMax;
  draw();
});
document.getElementById('step').addEventListener('click', () => {
  if (kMax < 8) {
    kMax++;
    document.getElementById('k').value = kMax;
    document.getElementById('kVal').textContent = kMax;
    draw();
  }
});
document.getElementById('reset').addEventListener('click', () => {
  kMax = 0;
  document.getElementById('k').value = 0;
  document.getElementById('kVal').textContent = 0;
  draw();
});

draw();
</script>

</body>
</html>
</artifact>

Open it and try the four equations in order:

1. **$\dot x = x$** — clean exponential, watch each Picard iterate add one more Taylor term.
2. **$\dot x = -2x$** — convergence is even faster because $L=2$ but the time interval is short.
3. **$\dot x = x^2$** — Lipschitz only *locally*; the true solution blows up at $t=1$, so the existence interval $\alpha = \min(a, b/M)$ is genuinely finite.
4. **$\dot x = \sqrt{|x|}$** — the killer. Not Lipschitz at $0$. Picard iteration gets stuck at $\varphi_k \equiv 0$, but $x(t)=t^2/4$ is *also* a solution. **Uniqueness fails.**

The fourth case is the whole reason Lipschitz appears in the hypothesis — you'll meet it again on Day 10.

Sure — here's a classic snake game. Use arrow keys or WASD.

<artifact type="html" id="snake-game" title="Snake game">
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 16px; background: #1a1a1a; color: #eee; display: flex; flex-direction: column; align-items: center; }
  h2 { margin: 0 0 8px 0; color: #8fc; }
  .info { display: flex; gap: 24px; font-size: 14px; margin-bottom: 8px; }
  .score { color: #ffd700; font-weight: 600; }
  canvas { border: 2px solid #444; border-radius: 4px; background: #0a0a0a; display: block; }
  .hint { font-size: 12px; color: #888; margin-top: 8px; text-align: center; }
  button { margin-top: 10px; padding: 8px 18px; background: #2a6; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 14px; }
  button:hover { background: #3b7; }
  .overlay { position: absolute; pointer-events: none; color: #f55; font-size: 28px; font-weight: 700; text-shadow: 0 0 8px black; }
</style>
</head>
<body>

<h2>🐍 Snake</h2>
<div class="info">
  <span>Score: <span class="score" id="score">0</span></span>
  <span>Best: <span class="score" id="best">0</span></span>
  <span>Length: <span id="len">3</span></span>
</div>
<div style="position:relative;">
  <canvas id="cv" width="400" height="400"></canvas>
  <div id="overlay" class="overlay" style="display:none; position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);"></div>
</div>
<button id="restart">Restart (Space)</button>
<div class="hint">Arrow keys or WASD to move · Space to restart · P to pause</div>

<script>
const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
const GRID = 20;
const CELLS = cv.width / GRID; // 20x20

let snake, dir, nextDir, food, score, alive, paused, tickMs, lastTick;
let best = +(localStorage.getItem('snake-best') || 0);
document.getElementById('best').textContent = best;

function reset() {
  snake = [{x:10,y:10},{x:9,y:10},{x:8,y:10}];
  dir = {x:1,y:0};
  nextDir = dir;
  spawnFood();
  score = 0;
  alive = true;
  paused = false;
  tickMs = 110;
  lastTick = performance.now();
  document.getElementById('score').textContent = 0;
  document.getElementById('len').textContent = snake.length;
  document.getElementById('overlay').style.display = 'none';
}

function spawnFood() {
  while (true) {
    const f = { x: Math.floor(Math.random()*CELLS), y: Math.floor(Math.random()*CELLS) };
    if (!snake.some(s => s.x===f.x && s.y===f.y)) { food = f; return; }
  }
}

function step() {
  if (!alive || paused) return;
  // commit queued direction (prevents 180° in same tick)
  if (nextDir.x !== -dir.x || nextDir.y !== -dir.y) dir = nextDir;
  const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
  // wall collision
  if (head.x < 0 || head.x >= CELLS || head.y < 0 || head.y >= CELLS) return die();
  // self collision
  if (snake.some(s => s.x===head.x && s.y===head.y)) return die();
  snake.unshift(head);
  if (head.x === food.x && head.y === food.y) {
    score += 10;
    document.getElementById('score').textContent = score;
    document.getElementById('len').textContent = snake.length;
    spawnFood();
    // speed up slightly
    if (tickMs > 55) tickMs -= 2;
  } else {
    snake.pop();
  }
}

function die() {
  alive = false;
  if (score > best) {
    best = score;
    localStorage.setItem('snake-best', best);
    document.getElementById('best').textContent = best;
  }
  const o = document.getElementById('overlay');
  o.textContent = 'Game Over';
  o.style.display = 'block';
}

function draw() {
  // background grid
  ctx.fillStyle = '#0a0a0a';
  ctx.fillRect(0,0,cv.width,cv.height);
  ctx.strokeStyle = '#1a1a1a';
  ctx.lineWidth = 1;
  for (let i=1;i<CELLS;i++){
    ctx.beginPath(); ctx.moveTo(i*GRID,0); ctx.lineTo(i*GRID,cv.height); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0,i*GRID); ctx.lineTo(cv.width,i*GRID); ctx.stroke();
  }
  // food (pulsing)
  const pulse = 1 + 0.15*Math.sin(performance.now()/200);
  const fs = GRID * 0.4 * pulse;
  ctx.fillStyle = '#f55';
  ctx.beginPath();
  ctx.arc(food.x*GRID + GRID/2, food.y*GRID + GRID/2, fs, 0, Math.PI*2);
  ctx.fill();
  ctx.shadowColor = '#f55'; ctx.shadowBlur = 10;
  ctx.fill();
  ctx.shadowBlur = 0;
  // snake
  snake.forEach((s, i) => {
    const head = i === 0;
    ctx.fillStyle = head ? '#8fc' : `hsl(${160 + i*2}, 60%, ${50 - Math.min(i,15)}%)`;
    const pad = head ? 1 : 2;
    ctx.fillRect(s.x*GRID + pad, s.y*GRID + pad, GRID - 2*pad, GRID - 2*pad);
    if (head) {
      // eyes
      ctx.fillStyle = '#000';
      const ex = s.x*GRID + GRID/2, ey = s.y*GRID + GRID/2;
      const off = 4;
      const px = dir.x * 2, py = dir.y * 2;
      // perpendicular offset for two eyes
      const ox = dir.y * off, oy = -dir.x * off;
      ctx.beginPath(); ctx.arc(ex + px + ox, ey + py + oy, 2, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(ex + px - ox, ey + py - oy, 2, 0, Math.PI*2); ctx.fill();
    }
  });
}

function loop(now) {
  if (now - lastTick >= tickMs) {
    step();
    lastTick = now;
  }
  draw();
  requestAnimationFrame(loop);
}

document.addEventListener('keydown', e => {
  const k = e.key.toLowerCase();
  if (k === 'arrowup' || k === 'w')    nextDir = {x:0,y:-1};
  else if (k === 'arrowdown' || k === 's')  nextDir = {x:0,y:1};
  else if (k === 'arrowleft' || k === 'a')  nextDir = {x:-1,y:0};
  else if (k === 'arrowright' || k === 'd') nextDir = {x:1,y:0};
  else if (k === ' ') { if (!alive) reset(); else paused = !paused; updatePauseOverlay(); }
  else if (k === 'p') { if (alive) { paused = !paused; updatePauseOverlay(); } }
  if (['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)) e.preventDefault();
});

function updatePauseOverlay() {
  const o = document.getElementById('overlay');
  if (paused && alive) { o.textContent = 'Paused'; o.style.display = 'block'; o.style.color = '#8fc'; }
  else if (alive) { o.style.display = 'none'; }
}

document.getElementById('restart').addEventListener('click', reset);

reset();
requestAnimationFrame(loop);
</script>

</body>
</html>
</artifact>

Features:
- Arrow keys or WASD to steer
- Space to restart (or pause mid-game), P to pause
- Speeds up gradually as you eat
- High score persists in localStorage

