I'll make you a self-contained HTML file with a Plotly phase portrait. Quick note: $\dot y = -y + \sin(x)$ with two variables $x,y$ is a bit ambiguous — I'll treat $x$ as an independent variable that also evolves ($\dot x = 1$), so the phase plane is $(x,y)$ with vector field $(1,\,-y+\sin x)$. That gives a proper 2D portrait.

```bash
cat > /tmp/phase.html << 'EOF'
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>Phase portrait: dy/dt = -y + sin(x)</title>
<script src="https://cdn.jsdelivr.net/npm/plotly.js-dist-min@2.35.2/plotly.min.js"></script>
<style>
  body { font-family: system-ui, sans-serif; margin: 20px; background: #111; color: #eee; }
  #plot { width: 900px; height: 600px; }
  .ctrl { margin: 10px 0; }
  label { margin-right: 12px; }
</style>
</head>
<body>
<h2>Phase portrait of $\dot x = 1,\ \dot y = -y + \sin x$</h2>
<div class="ctrl">
  <label>grid density: <input type="range" id="density" min="10" max="40" value="22"></label>
  <label>arrow scale: <input type="range" id="scale" min="1" max="20" value="8"></label>
  <button id="clear">clear trajectories</button>
  <span style="margin-left:12px;opacity:.7">click on the plot to drop a trajectory</span>
</div>
<div id="plot"></div>

<script>
const xmin=-8, xmax=8, ymin=-3, ymax=3;

function vectorField(x,y){ return [1, -y + Math.sin(x)]; }

function buildQuiver(N, scale){
  const xs=[], ys=[];
  const dx=(xmax-xmin)/N, dy=(ymax-ymin)/N;
  // normalize arrow length
  const L = Math.min(dx,dy)*0.9;
  for(let i=0;i<=N;i++){
    for(let j=0;j<=N;j++){
      const x=xmin+i*dx, y=ymin+j*dy;
      const [u,v]=vectorField(x,y);
      const m=Math.hypot(u,v)||1;
      const ux=u/m, vy=v/m;
      const x2=x+ux*L*scale/10, y2=y+vy*L*scale/10;
      xs.push(x, x2, null);
      ys.push(y, y2, null);
    }
  }
  return {xs, ys};
}

// nullclines: dy/dt = 0 => y = sin(x). dx/dt is always 1 so no x-nullcline.
function nullcline(){
  const xs=[], ys=[];
  for(let x=xmin; x<=xmax; x+=0.05){ xs.push(x); ys.push(Math.sin(x)); }
  return {xs, ys};
}

function rk4(x,y,dt){
  const k1=vectorField(x,y);
  const k2=vectorField(x+dt*k1[0]/2, y+dt*k1[1]/2);
  const k3=vectorField(x+dt*k2[0]/2, y+dt*k2[1]/2);
  const k4=vectorField(x+dt*k3[0],   y+dt*k3[1]);
  return [x + dt*(k1[0]+2*k2[0]+2*k3[0]+k4[0])/6,
          y + dt*(k1[1]+2*k2[1]+2*k3[1]+k4[1])/6];
}

function trajectory(x0,y0){
  const xs=[x0], ys=[y0];
  // forward
  let x=x0,y=y0;
  for(let k=0;k<2000;k++){
    [x,y]=rk4(x,y,0.02);
    if(x<xmin-1||x>xmax+1||y<ymin-2||y>ymax+2) break;
    xs.push(x); ys.push(y);
  }
  // backward
  x=x0; y=y0;
  const bx=[], by=[];
  for(let k=0;k<2000;k++){
    [x,y]=rk4(x,y,-0.02);
    if(x<xmin-1||x>xmax+1||y<ymin-2||y>ymax+2) break;
    bx.push(x); by.push(y);
  }
  return {xs:[...bx.reverse(),...xs], ys:[...by.reverse(),...ys]};
}

const layout = {
  paper_bgcolor:'#111', plot_bgcolor:'#111',
  font:{color:'#ddd'},
  xaxis:{range:[xmin,xmax], title:'x', gridcolor:'#333', zerolinecolor:'#555'},
